using System;using System.IO;using System.Collections.Generic;using System.Reflection;using System.Linq;using Ingestion;
static class PluginFactory {public static string Mode="dynamic";public static IFormatPlugin[] Create(Options o){var plugins=new List<IFormatPlugin>();foreach(string file in Directory.GetFiles(o.Plugins,"*.dll").OrderBy(x=>x,StringComparer.Ordinal)){var assembly=Assembly.LoadFrom(file);foreach(var type in assembly.GetTypes().Where(t=>typeof(IFormatPlugin).IsAssignableFrom(t)&&!t.IsAbstract&&!t.IsInterface))plugins.Add((IFormatPlugin)Activator.CreateInstance(type));}if(plugins.Count==0)throw new InvalidDataException("NO_PLUGIN_DLLS_FOUND");return plugins.ToArray();}}
